"""Failure/acknowledgment and interrupted-entry checks against real Spring + PostgreSQL."""
from urllib.parse import urljoin
from datetime import datetime
from zoneinfo import ZoneInfo
import base64
from playwright.sync_api import expect


def verify_daily_reliability(page, base, output):
    day=datetime.now(ZoneInfo('Europe/Warsaw')).date().isoformat()
    page.goto(base+'/calendar?add=true');f=page.locator('#booking-form');f.locator('[data-category-choice="1"]').click();f.locator('[name=qty_2]').fill('1');f.locator('[name=name]').fill('Niezawodność QA');f.locator('[name=phone]').fill('500000099');f.locator('[name=address]').fill('Adres testowy');f.get_by_role('button',name='Zapisz zlecenie',exact=True).click();expect(page.locator('#booking-editor')).not_to_be_visible();booking=page.locator('#agenda-orders [data-order]').filter(has_text='Niezawodność QA').get_attribute('data-order')
    page.goto(base+'/work/'+booking);page.locator('#photos>summary').click();page.locator('#photos details>summary').click();f=page.locator('#photo-time-form');f.locator('[name=start]').fill(day+'T09:00');f.locator('[name=end]').fill(day+'T09:45');f.get_by_role('button',name='Zapisz godziny',exact=True).click();expect(page.locator('#photos .photo-status').first).to_contain_text('Zapisano.');expect(page.locator('form[action$="/timer"] [name=version]')).to_have_value(page.locator('#service-photo-form [name=version]').input_value());expect(page.locator('.timer-disclosure>summary')).to_contain_text('45 min')
    page.locator('.timer-disclosure>summary').click();page.get_by_role('button',name='Rozpocznij pracę',exact=True).click();expect(page.get_by_role('button',name='Zakończ pomiar',exact=True)).to_be_visible();page.get_by_role('button',name='Zakończ pomiar',exact=True).click();expect(page.locator('.timer-disclosure [name=action]')).to_have_value('start')
    page.goto(base+'/notes');page.locator('[data-note-new]').click();f=page.locator('#note-form');f.locator('[name=title]').fill('Szkic audytu');f.locator('[name=content]').fill('Nie gub tego tekstu');page.locator('[data-note-close]').click();page.locator('[data-note-new]').click();expect(f).to_be_visible();expect(f.locator('[name=title]')).to_have_value('Szkic audytu');expect(page.locator('[data-editor-draft]')).to_be_visible()
    page.get_by_role('button',name='Odrzuć szkic',exact=True).click();expect(f.locator('[name=title]')).to_have_value('');f.locator('[name=title]').fill('Zapis po przerwie QA')
    # A successful mutation followed by a failed list read is still a successful save.
    held=[]
    def delay_list(route):
        if route.request.method=='GET':held.append(route)
        else:route.continue_()
    page.route('**/notes',delay_list,times=2)
    f.get_by_role('button',name='Zapisz',exact=True).click();expect(page.locator('#note-editor')).not_to_be_visible();page.locator('[data-note-new]').click();expect(f).to_be_visible();expect(f.locator('[name=title]')).to_have_value('');held[0].fulfill(status=503,body='Read failed');expect(page.locator('.note-live')).to_contain_text('Dane zapisane');page.locator('[data-note-close]').click();assert 'Zapis po przerwie QA' in page.request.get(base+'/notes').text();page.unroute('**/notes');page.reload();expect(page.locator('.memo-card').filter(has_text='Zapis po przerwie QA')).to_have_count(1)
    page.locator('[data-note-new]').click();f=page.locator('#note-form');f.locator('[name=title]').fill('Szkic między edycjami');page.locator('[data-note-close]').click();page.locator('.memo-card').filter(has_text='Zapis po przerwie QA').locator('[data-note-edit]').click();expect(f.locator('[name=title]')).to_have_value('Zapis po przerwie QA');page.locator('[data-note-close]').click();page.locator('[data-note-new]').click();expect(f.locator('[name=title]')).to_have_value('Szkic między edycjami');page.get_by_role('button',name='Odrzuć szkic',exact=True).click();expect(f.locator('[name=title]')).to_have_value('');page.locator('[data-note-close]').click()
    # Cost drafts preserve their fields and the selected receipt file across editor switches.
    page.goto(base+'/costs');page.locator('[data-cost-new]').click();f=page.locator('#cost-form');f.locator('[name=title]').fill('Szkic kosztu QA');f.locator('[name=amount]').fill('12.50');f.locator('.cost-extra>summary').click();f.locator('[data-cost-receipt]').first.set_input_files({'name':'rachunek.png','mimeType':'image/png','buffer':base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAoAAAAKCAIAAAACUFjqAAAAFUlEQVR4nGPccfcXA27AhEduBEsDACFJAqNlg1pJAAAAAElFTkSuQmCC')});page.locator('[data-cost-close]').click();page.locator('[data-cost-new]').click();expect(f).to_be_visible();expect(f.locator('[name=title]')).to_have_value('Szkic kosztu QA');expect(f.locator('[name=amount]')).to_have_value('12.50');assert f.locator('[data-cost-receipt]').first.evaluate('e=>e.files.length')==1
    for width in (360,390,768,1440):
        page.set_viewport_size({'width':width,'height':844});assert f.evaluate('e=>e.scrollWidth<=e.clientWidth');page.screenshot(path=str(output/('reliability-draft-'+str(width)+'.png')))
    page.route('**/costs',lambda r:r.fulfill(status=503,body='Read failed') if r.request.method=='GET' else r.continue_(),times=2);f.get_by_role('button',name='Zapisz wydatek',exact=True).click();expect(page.locator('#cost-editor')).not_to_be_visible();expect(page.locator('.cost-live')).to_contain_text('Dane zapisane');page.reload();row=page.locator('.expense-row').filter(has_text='Szkic kosztu QA');expect(row).to_have_count(1);receipt=row.get_by_role('link',name='Rachunek',exact=False).get_attribute('href');assert page.request.get(urljoin(page.url,receipt)).status==200
    print('PASS reliability: photo-time/timer synchronization, draft resume/discard, save acknowledged despite failed refresh, cost draft/four widths.',flush=True)
